//! Algebraic laws of the join, the codec and the state hash, over small random
//! states.
//!
//! States are generated by running `Writer` operations on four writers and
//! exchanging whole states between them (the way writers' states actually come
//! to exist: every state is the result of local writes, which normalise through
//! a join with the empty state, and of joins). The laws are not claimed for
//! arbitrary hand-built states. Every intermediate state of the run is pooled.
//! A seeded xorshift keeps the runs reproducible.

use std::collections::BTreeSet;

use super::*;
use crate::hlc::Hlc;
use crate::ids::NodeId;

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
    fn pick<'a, T>(&mut self, xs: &'a [T]) -> &'a T {
        &xs[self.below(xs.len())]
    }
}

fn opts(ret: u64) -> JoinOptions {
    JoinOptions { retention: ret, ..JoinOptions::default() }
}

/// One random run; returns every state any writer held along the way.
fn run(seed: u64, steps: usize, o: &JoinOptions) -> Vec<MergeState> {
    let mut rng = Rng(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1);
    let n = 3 + rng.below(2);
    let mut ws: Vec<Writer> = (0..n)
        .map(|k| {
            let id = WriterId {
                node: NodeId::from_bytes([b'A' + k as u8; 16]),
                epoch: Epoch::from_u64(0),
            };
            Writer::new(id, o.clone())
        })
        .collect();
    let mut pool = Vec::new();
    ws[0].insert(&[("x", Value::Int(100)), ("n", Value::Str("a".into()))], 0);
    for _ in 0..steps {
        let m = rng.below(n);
        let skew = *rng.pick(&[0, 0, 0, 4]);
        if rng.below(100) < 45 {
            let mut other = rng.below(n);
            if other == m {
                other = (m + 1) % n;
            }
            let st = ws[other].state.clone();
            ws[m].receive(&st);
        } else {
            let p = *rng.pick(&["x", "n", "y"]);
            let w = &mut ws[m];
            match rng.below(10) {
                0 => {
                    w.insert(&[(*rng.pick(&["x", "y"]), Value::Int(*rng.pick(&[1, 2])))], skew);
                }
                1 => {
                    w.upsert_inc(rng.pick(&["x", "y"]), *rng.pick(&[1, 2]), skew);
                }
                2 => {
                    let v =
                        rng.pick(&[Value::Int(7), Value::Int(8), Value::Str("s".into())]).clone();
                    w.write_replace(&[(*rng.pick(&["x", "n", "y"]), v)], skew);
                }
                3..=5 => {
                    w.write_inc(p, *rng.pick(&[1, 5, 20, -3]), skew);
                }
                6 | 7 => {
                    let v = &rng
                        .pick(&[
                            Value::Int(0),
                            Value::Int(7),
                            Value::Int(500),
                            Value::Str("s".into()),
                            Value::Double(2.5),
                        ])
                        .clone();
                    w.write_set(p, v.clone(), skew);
                }
                8 => {
                    w.write_unset(p, skew);
                }
                _ => {
                    w.write_delete(skew);
                }
            }
        }
        pool.push(ws[m].state.clone());
    }
    pool
}

fn pools(seeds: u64, steps: usize, o: &JoinOptions) -> Vec<Vec<MergeState>> {
    (1..=seeds).map(|s| run(s, steps, o)).collect()
}

fn triples(
    pools: &[Vec<MergeState>],
    count: usize,
) -> Vec<(&MergeState, &MergeState, &MergeState)> {
    let mut rng = Rng(0xDEAD_BEEF_1234_5678);
    (0..count)
        .map(|_| {
            let p = &pools[rng.below(pools.len())];
            (&p[rng.below(p.len())], &p[rng.below(p.len())], &p[rng.below(p.len())])
        })
        .collect()
}

/// The state without its loss records.
fn bare(mut s: MergeState) -> MergeState {
    s.losses.clear();
    s
}

/// NOTE(model): the loss RECORDS are not an associative function of the states: a clash or a
/// deleteWon is detected when the two sides that hold the evidence meet, so `(a+b)+c` and `a+(b+c)`
/// can hold different records (the cluster converges on records by pulling the loss entries, probe
/// P5, not by the join). Everything else in the state is a join-semilattice. So associativity is
/// asserted on the state without records; the records are asserted commutative, idempotent and
/// monotone (never lost before the horizon), and fresh keys are checked exactly.
///
/// NOTE(model): with a SMALL retention the state itself is not exactly associative either: the
/// horizon is taken from the joined version vector, so `(a+b)+c` and `a+(b+c)` prune at different
/// moments when a state far behind the others (an old alive life, its slots) is joined across the
/// horizon. The model does not claim convergence across a partition longer than retention
/// (model5.main: "tiny-retention runs"), and the same holds here. `exact_assoc` is therefore set
/// only for retentions that the generated runs do not outrun; for small ones the rate of
/// differing triples is bounded instead (observed 0.5 percent at R from 2 to 6).
fn check_laws(o: &JoinOptions, exact_assoc: bool, seeds: u64, steps: usize, count: usize) {
    let ps = pools(seeds, steps, o);
    let mut assoc_loss_diff = 0;
    let mut assoc_state_diff = 0;
    for (k, (a, b, c)) in triples(&ps, count).into_iter().enumerate() {
        let j = |x: &MergeState, y: &MergeState| join(x, y, o).0;
        let ab = j(a, b);
        let ba = j(b, a);
        assert!(ab == ba, "commutative (state and records), triple {k}");
        let l = j(&ab, c);
        let r = j(a, &j(b, c));
        let assoc_ok = bare(l.clone()) == bare(r.clone());
        assert!(assoc_ok || !exact_assoc, "associative (state), triple {k}");
        assoc_state_diff += usize::from(!assoc_ok);
        assoc_loss_diff += usize::from(l.losses != r.losses);
        assert!(j(a, a) == *a, "idempotent (state and records), triple {k}");
        assert!(j(&ab, b) == ab, "absorbing (state and records), triple {k}");
        // Fresh keys are exactly the records the result has and `a` lacked.
        let (m, fresh) = join(a, b, o);
        let want: BTreeSet<_> =
            m.losses.keys().filter(|k| !a.losses.contains_key(*k)).cloned().collect();
        assert_eq!(fresh, want);
        // Monotone: records of `a` survive the join unless the joined horizon passed them.
        let hz = ab.horizon(o);
        assert!(
            a.losses.keys().all(|k| ab.losses.contains_key(k) || k.stamp.hlc < hz),
            "monotone, triple {k}"
        );
        // The hash does not depend on the join order.
        assert_eq!(ab.state_hash(), ba.state_hash());
    }
    // Not a law: report-only, so the NOTE above stays honest.
    assert!(
        assoc_state_diff * 50 <= count,
        "state associativity differed in {assoc_state_diff} of {count}"
    );
    eprintln!(
        "associativity differed: state {assoc_state_diff}, records {assoc_loss_diff} of {count} triples"
    );
}

#[test]
fn join_laws_large_retention() {
    check_laws(&opts(1_000_000_000), true, 60, 24, 300);
}

#[test]
fn join_laws_small_retention() {
    // Small R exercises the horizon-first filter: records and lives fall behind the joined horizon.
    check_laws(&opts(6), false, 60, 24, 300);
    check_laws(&opts(3), false, 60, 30, 200);
    check_laws(&opts(10), true, 60, 30, 300);
}

#[test]
fn encode_decode_round_trip() {
    for o in [opts(1_000_000_000), opts(6)] {
        let mut seen_gens = false;
        let mut seen_losses = false;
        for pool in pools(40, 24, &o) {
            for st in &pool {
                let bytes = st.encode();
                let back = MergeState::decode(&bytes).expect("decode");
                assert_eq!(&back, st);
                assert_eq!(back.canonical_bytes(), st.canonical_bytes());
                assert_eq!(back.state_hash(), st.state_hash());
                seen_gens |= !st.gens.is_empty();
                seen_losses |= !st.losses.is_empty();
            }
        }
        assert!(seen_gens && seen_losses, "the generated states should exercise gens and losses");
    }
    let empty = MergeState::default();
    assert_eq!(MergeState::decode(&empty.encode()).unwrap(), empty);
}

#[test]
fn decode_refuses_damaged_input() {
    let o = opts(1_000_000_000);
    let pool = run(7, 24, &o);
    let bytes = pool.last().unwrap().encode();
    assert_eq!(MergeState::decode(&[]), Err(DecodeError::Truncated));
    assert_eq!(MergeState::decode(b"XXXX"), Err(DecodeError::BadHeader));
    for cut in 0..bytes.len() {
        assert!(MergeState::decode(&bytes[..cut]).is_err(), "cut {cut}");
    }
    let mut longer = bytes.clone();
    longer.push(0);
    assert_eq!(MergeState::decode(&longer), Err(DecodeError::Trailing(1)));
}

#[test]
fn state_hash_of_different_join_orders_is_equal() {
    // Every pooled state is joined into one, in two different orders. The state without records
    // is equal outright; the records converge by pulling the loss entries (model probe P5), done
    // here by `receive_loss` of the other side's records, after which the hashes are equal.
    let o = opts(1_000_000_000);
    for pool in pools(30, 24, &o) {
        let fwd = pool.iter().fold(MergeState::default(), |acc, s| join(&acc, s, &o).0);
        let mut rev_order: Vec<&MergeState> = pool.iter().collect();
        rev_order.reverse();
        let rev = rev_order.into_iter().fold(MergeState::default(), |acc, s| join(s, &acc, &o).0);
        assert!(bare(fwd.clone()) == bare(rev.clone()));
        let mut wf = Writer::from_state(
            WriterId { node: NodeId::from_bytes([b'F'; 16]), epoch: Epoch::from_u64(0) },
            fwd.clone(),
            o.clone(),
        );
        let mut wr = Writer::from_state(
            WriterId { node: NodeId::from_bytes([b'R'; 16]), epoch: Epoch::from_u64(0) },
            rev.clone(),
            o.clone(),
        );
        for (k, v) in &rev.losses {
            wf.receive_loss(k.clone(), v.clone());
        }
        for (k, v) in &fwd.losses {
            wr.receive_loss(k.clone(), v.clone());
        }
        assert!(wf.state == wr.state);
        assert_eq!(wf.state.state_hash(), wr.state.state_hash());
        assert_eq!(wf.state.canonical_bytes(), wr.state.canonical_bytes());
    }
}

#[test]
fn state_hash_separates_states() {
    let o = opts(1_000_000_000);
    let mut hashes = BTreeSet::new();
    let mut states = BTreeSet::new();
    for pool in pools(40, 24, &o) {
        for st in pool {
            hashes.insert(st.state_hash());
            states.insert(st.canonical_bytes());
        }
    }
    assert_eq!(hashes.len(), states.len());
}

#[test]
fn writer_state_hash_equals_receivers() {
    // A writer's normalised state hashes like the state a receiver reaches by joining it in.
    let o = opts(1_000_000_000);
    for pool in pools(30, 24, &o) {
        for st in &pool {
            let recv = join(&MergeState::default(), st, &o).0;
            assert_eq!(recv.state_hash(), st.state_hash());
        }
    }
}

#[test]
fn local_refusals_and_noops() {
    let o = opts(1_000_000_000);
    let id = WriterId {
        node: NodeId::from_bytes([b'A'; 16]),
        epoch: Epoch::new(Hlc::new(5, 1), [9; 8]),
    };
    let mut w = Writer::new(id, o);
    assert!(w.write_set("x", Value::Int(1), 0).is_none(), "no life");
    assert!(w.write_delete(0).is_none());
    let a = w.insert(&[("x", Value::Int(1))], 0).unwrap();
    assert_eq!(a.record.kind, WriteKind::Insert);
    assert!(w.insert(&[("y", Value::Int(1))], 0).is_none(), "a life is alive");
    assert!(w.write_set("x", Value::Int(1), 0).is_none(), "unchanged");
    assert!(w.write_unset("nope", 0).is_none());
    assert!(w.write_inc("x", i64::MAX, 0).is_none(), "past the bound");
    w.write_set("s", Value::Str("t".into()), 0).unwrap();
    assert!(w.write_inc("s", 1, 0).is_none(), "a string");
    assert!(w.write_replace(&[("x", Value::Int(1)), ("s", Value::Str("t".into()))], 0).is_none());
    let r = w.write_replace(&[("x", Value::Int(2))], 0).unwrap();
    assert_eq!(r.record.paths, vec!["x".to_string(), "s".to_string()]);
    assert_eq!(w.visible().unwrap().len(), 1);
    w.write_delete(0).unwrap();
    assert!(w.visible().is_none());
}

#[test]
fn mutants_change_the_outcome() {
    // Each switch, set wrong, must visibly change the V6M1 / Q2 scenarios (so the probes can kill it).
    let mk = |o: &JoinOptions, c: u8| {
        Writer::new(
            WriterId { node: NodeId::from_bytes([c; 16]), epoch: Epoch::from_u64(0) },
            o.clone(),
        )
    };
    let run = |o: &JoinOptions| {
        let (mut a, mut b, mut c) = (mk(o, b'A'), mk(o, b'B'), mk(o, b'C'));
        a.insert(&[("x", Value::Int(1))], 0).unwrap();
        c.receive(&a.state.clone());
        c.write_set("note", Value::Str("c".into()), 0).unwrap();
        b.clock = Hlc::new(8, 0);
        b.insert(&[("y", Value::Int(2))], 0).unwrap();
        let mut o1 = mk(o, b'O');
        o1.receive(&a.state.clone());
        o1.receive(&c.state.clone());
        o1.receive(&b.state.clone());
        (o1.visible(), o1.state.losses.len())
    };
    let good = run(&opts(1_000_000_000));
    assert_eq!(good.1, 2); // insertLost on the document and on c's note
    let no_cells = run(&JoinOptions { cells_reported: false, ..opts(1_000_000_000) });
    assert!(no_cells.1 < good.1);
    let no_sup = run(&JoinOptions { supersede: false, ..opts(1_000_000_000) });
    assert_ne!(no_sup.0, good.0);
}
